"""Write a LAMMPS data file and input script from ASE atoms and an explicit potential.

No potential is built in: ``pair_style`` and ``pair_coeff`` must be supplied by the caller,
and any potential file they name is hashed into the input record. The script ends with
``write_data`` and a per-atom dump so the final state can be read back.
"""

from __future__ import annotations

import json
import shlex
from dataclasses import dataclass, field
from pathlib import Path
from typing import Literal

from ase import Atoms
from ase.io import write as ase_write

from matsim_agents.core.hashing import sha256_file
from matsim_agents.core.seeding import stream_seed

INPUT_NAME = "in.lammps"
DATA_NAME = "structure.data"
LOG_NAME = "log.lammps"
FINAL_DATA = "final.data"
FINAL_DUMP = "final.dump"
INPUT_RECORD = "input_record.json"
Task = Literal["single_point", "minimize", "nvt", "nve"]


class LammpsInputError(ValueError):
    pass


@dataclass(frozen=True)
class Potential:
    pair_style: str
    pair_coeff: tuple[str, ...]
    files: tuple[str, ...] = ()  # potential files to hash into the record

    def __post_init__(self) -> None:
        if not self.pair_style.strip() or not self.pair_coeff:
            raise LammpsInputError("pair_style and at least one pair_coeff line are required")
        for line in (self.pair_style, *self.pair_coeff):
            if "\n" in line:
                raise LammpsInputError("pair_style/pair_coeff entries must be single lines")


@dataclass(frozen=True)
class LammpsTask:
    task: Task = "single_point"
    steps: int = 0
    timestep_ps: float = 0.001
    temperature_k: float | None = None
    seed: int | None = None
    thermo_every: int = 100
    etol: float = 1e-8
    ftol: float = 1e-8
    max_iterations: int = 10000
    extra_commands: tuple[str, ...] = field(default=())

    def __post_init__(self) -> None:
        if self.task in ("nvt", "nve") and self.steps <= 0:
            raise LammpsInputError(f"task {self.task!r} needs steps > 0")
        if self.task == "nvt" and self.temperature_k is None:
            raise LammpsInputError("task 'nvt' needs temperature_k")
        if self.temperature_k is not None and self.seed is None:
            raise LammpsInputError("an initial temperature needs an explicit seed")


def _species(atoms: Atoms) -> list[str]:
    seen: list[str] = []
    for s in atoms.get_chemical_symbols():
        if s not in seen:
            seen.append(s)
    return seen


def render_script(species: list[str], potential: Potential, task: LammpsTask) -> str:
    lines = [
        "# generated by matsim-agents; potential supplied by the user",
        "units metal",
        "atom_style atomic",
        "boundary p p p",
        f"read_data {DATA_NAME}",
        f"pair_style {potential.pair_style}",
        *(f"pair_coeff {c}" for c in potential.pair_coeff),
        "neighbor 2.0 bin",
        "neigh_modify every 1 delay 0 check yes",
        "thermo_style custom step temp pe ke etotal press vol",
        "thermo_modify format float %.10g",
        f"thermo {task.thermo_every}",
        *task.extra_commands,
    ]
    if task.temperature_k is not None:
        seed = stream_seed(task.seed, "lammps-velocity")
        lines.append(f"velocity all create {task.temperature_k} {max(seed, 1)} dist gaussian")
    if task.task == "single_point":
        lines.append("run 0")
    elif task.task == "minimize":
        lines += [
            "min_style cg",
            f"minimize {task.etol} {task.ftol} {task.max_iterations} {10 * task.max_iterations}",
        ]
    else:
        lines.append(f"timestep {task.timestep_ps}")
        if task.task == "nvt":
            damp = 100 * task.timestep_ps
            t = task.temperature_k
            lines.append(f"fix integrate all nvt temp {t} {t} {damp}")
        else:
            lines.append("fix integrate all nve")
        lines.append(f"run {task.steps}")
    type_names = " ".join(species)
    lines += [
        f"write_data {FINAL_DATA}",
        f"write_dump all custom {FINAL_DUMP} id type x y z fx fy fz "
        f"modify sort id element {type_names}",
        'print "MATSIM_LAMMPS_DONE"',
    ]
    return "\n".join(lines) + "\n"


def write_inputs(atoms: Atoms, run_dir: Path, potential: Potential, task: LammpsTask) -> Path:
    """Write the data file, input script and an input record; return the script path."""
    if len(atoms) == 0:
        raise LammpsInputError("atoms are empty")
    if not all(atoms.pbc):
        raise LammpsInputError("only fully periodic cells are supported")
    run_dir.mkdir(parents=True, exist_ok=True)
    species = _species(atoms)
    ase_write(
        run_dir / DATA_NAME,
        atoms,
        format="lammps-data",
        specorder=species,
        masses=True,
        units="metal",
        atom_style="atomic",
    )
    script = run_dir / INPUT_NAME
    script.write_text(render_script(species, potential, task))
    files = {}
    for name in potential.files:
        path = Path(name).expanduser()
        if not path.is_file():
            raise LammpsInputError(f"potential file not found: {name}")
        files[str(path.resolve())] = sha256_file(path)
    record = {
        "species_order": species,
        "n_atoms": len(atoms),
        "pair_style": potential.pair_style,
        "pair_coeff": list(potential.pair_coeff),
        "potential_files_sha256": files,
        "task": task.task,
        "steps": task.steps,
        "temperature_k": task.temperature_k,
        "seed": task.seed,
        "script_sha256": sha256_file(script),
        "data_sha256": sha256_file(run_dir / DATA_NAME),
    }
    (run_dir / INPUT_RECORD).write_text(json.dumps(record, indent=2, sort_keys=True) + "\n")
    return script


def potential_from_file(
    pair_style: str, potential_file: str | Path, species: list[str]
) -> Potential:
    """Common ``pair_coeff * * <file> <species...>`` form (eam/alloy, eam/fs, ...)."""
    path = str(Path(potential_file).expanduser())
    coeff = f"* * {shlex.quote(path)} {' '.join(species)}"
    return Potential(pair_style=pair_style, pair_coeff=(coeff,), files=(path,))


__all__ = [
    "DATA_NAME",
    "FINAL_DATA",
    "FINAL_DUMP",
    "INPUT_NAME",
    "INPUT_RECORD",
    "LOG_NAME",
    "LammpsInputError",
    "LammpsTask",
    "Potential",
    "potential_from_file",
    "render_script",
    "write_inputs",
]
